// H3 Compose the weekly note - Run Once For All Items. The reasoning node of the weekly heartbeat.
//
// What it answers, in one message a week: is the runtime alive, and is the club's calendar actually full?
// Both questions matter because every other message on this topic means "something happened" (D194), so
// silence means either "quiet" or "dead" and a person cannot tell (D205).
//
// What it does NOT do: plan. It never calls `planSeries`. The heartbeat is not a second planner - a second
// planner is a second opinion, and two vocabularies for one calendar is how a message stops being evidence. It
// reports the rows that exist, read in the same wall-clock terms the planner uses, and makes exactly one
// judgement: how many days until the next one, against the same 21-day runway A8's `check:ics` gates the site
// on (D188). Past it, the note goes to priority 4 and names the fixing command.
//
// There is no `Tell a person?` gate anywhere in this workflow, and `checkHeartbeat()` fails the build if one
// is ever added: a heartbeat that can be skipped is indistinguishable from the failure it exists to detect.
//
// GENERATED FROM integrations/mobilizon-cadence/nodes/41-heartbeat-note.js - edit that file and rebuild.

/**
 * cadence core - every rule this integration follows, in pure functions with no imports.
 *
 * It has no dependencies on purpose. The same text runs in two hosts: Node here (tests, `simulate.mjs`) and
 * an n8n Code node (`build-workflow.mjs` inlines it, stripping the word `export`). A rule that exists in one
 * host and not the other is the failure this file is built to prevent, so the two hosts are not allowed to
 * own logic of their own - the adapters around this file only move items.
 *
 * What the rules are for: Mobilizon has no repeating events, so a series only exists as a row per date.
 * Someone, or something, has to make the next one. Everything below is that decision made the same way
 * every time, with the clock question treated as the hard part rather than an implementation detail.
 *
 * The clock rule (the one that matters most here):
 *   Mobilizon stores a true UTC instant in `beginsOn`, and renders it in the **event's own**
 *   `options.timezone`. Measured 2026-11-04 on this instance: the three May/June rows sit at `17:00Z` with
 *   `options.timezone: null` (12:00 CDT, right), while the two November rows sit at `12:00Z`/`18:00Z` with
 *   `options.timezone: "Etc/UTC"` - the same wall clock the organizer typed, but filed as a UTC instant, so
 *   a subscriber's calendar shows them six hours early. D174 confirms the club's hours from the organizer's
 *   own entry and the club's own page, not from the `Z`.
 *   So: a date is read as wall clock in the row's own zone (falling back to the series zone when the row
 *   declares none), the next date is computed on calendar days, and the new instant is rebuilt from the
 *   carried wall clock in the **series'** declared zone. A row whose declared zone disagrees with the
 *   series' is reported, never quietly reinterpreted.
 */

// ---------------------------------------------------------------- titles

/** Series matching is on the organizer's own title text, so it has to be forgiving of spacing and case. */
const normTitle = (s) => String(s ?? "").trim().replace(/\s+/g, " ").toLowerCase();

function matchesSeries(series, row) {
  const t = normTitle(row.title);
  if (!t) return false;
  if (t === normTitle(series.title)) return true;
  return (series.aliases ?? []).some((a) => normTitle(a) === t);
}

// ------------------------------------------------- calendar date arithmetic
// All of it happens on plain `YYYY-MM-DD` calendar dates, never on a `Date` with a zone attached. A
// biweekly club meeting is a date, and the moment you turn a date into an instant you have chosen a
// timezone - which is the exact choice this file wants to make once, on purpose.

const DAY_MS = 86_400_000;

function parseDate(str) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(str ?? "").trim());
  if (!m) throw new Error(`not a YYYY-MM-DD date: ${JSON.stringify(str)}`);
  const [y, mo, d] = m.slice(1).map(Number);
  const t = Date.UTC(y, mo - 1, d);
  if (Number.isNaN(t) || new Date(t).getUTCFullYear() !== y || new Date(t).getUTCMonth() !== mo - 1 || new Date(t).getUTCDate() !== d) {
    throw new Error(`not a real calendar date: ${str}`);
  }
  return t;
}

const fmtDate = (ms) => new Date(ms).toISOString().slice(0, 10);
const addDays = (str, n) => fmtDate(parseDate(str) + n * DAY_MS);
const weekdayOf = (str) => new Date(parseDate(str)).getUTCDay(); // 0 = Sunday
const cmpDate = (a, b) => (parseDate(a) === parseDate(b) ? 0 : parseDate(a) < parseDate(b) ? -1 : 1);

/** Move forward (never back) to the given weekday. Forward-only is a rule, not an accident: pulling a
 *  meeting earlier is a decision about the club, pushing it later is only a decision about the slot. */
function snapToWeekday(str, weekday) {
  if (weekday === null || weekday === undefined) return str;
  const w = Number(weekday);
  if (!Number.isInteger(w) || w < 0 || w > 6) throw new Error(`weekday must be 0..6, got ${JSON.stringify(weekday)}`);
  for (let i = 0; i <= 6; i++) {
    const c = addDays(str, i);
    if (weekdayOf(c) === w) return c;
  }
  throw new Error("unreachable: weekday snap");
}

/** Add minutes to a wall clock time. Returns the day roll, because "12:00 + 150 min" is a different date. */
function addMinutesToTime(time, minutes) {
  if (!/^\d{2}:\d{2}$/.test(String(time))) throw new Error(`not HH:MM: ${JSON.stringify(time)}`);
  const total = Number(time.slice(0, 2)) * 60 + Number(time.slice(3, 5)) + Number(minutes);
  if (total < 0 || total >= 24 * 60 + 1440) throw new Error(`time out of range: ${time} + ${minutes}`);
  const dayShift = Math.floor(total / 1440);
  const inDay = total % 1440;
  return { time: `${String(Math.floor(inDay / 60)).padStart(2, "0")}:${String(inDay % 60).padStart(2, "0")}`, dayShift };
}

// ---------------------------------------------------------------- zones

const dtfCache = new Map();
function dtfFor(tz) {
  if (!dtfCache.has(tz)) {
    dtfCache.set(tz, new Intl.DateTimeFormat("en-US", {
      timeZone: tz, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", second: "2-digit",
    }));
  }
  return dtfCache.get(tz);
}

function assertTimezone(tz) {
  if (typeof tz !== "string" || !tz) throw new Error(`timezone must be a non-empty IANA string, got ${JSON.stringify(tz)}`);
  try { new Intl.DateTimeFormat("en-US", { timeZone: tz }); } catch { throw new Error(`unknown IANA timezone ${JSON.stringify(tz)}`); }
  return tz;
}

/** The wall clock an instant shows in `tz`, as text: "2026-11-21T12:00:00". */
function wallText(tz, ms) {
  const p = {};
  for (const part of dtfFor(tz).formatToParts(new Date(ms))) if (part.type !== "literal") p[part.type] = part.value;
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}`;
}

function wallClock(iso, tz) {
  assertTimezone(tz);
  const ms = Date.parse(String(iso ?? ""));
  if (Number.isNaN(ms)) throw new Error(`not an instant: ${JSON.stringify(iso)}`);
  const text = wallText(tz, ms);
  return { date: text.slice(0, 10), time: text.slice(11, 16), tz };
}

function offsetMinutes(tz, ms) {
  return (Date.parse(wallText(tz, ms) + "Z") - ms) / 60_000;
}

/**
 * The wall clock -> instant direction, done twice because one pass is not enough across a DST boundary,
 * and then verified: if the instant we computed does not render back as the clock we asked for, that clock
 * does not exist (the spring-forward gap) and the run must stop rather than ship an hour that never happened.
 */
function instantFrom(dateStr, time, tz) {
  assertTimezone(tz);
  if (!/^\d{2}:\d{2}$/.test(String(time))) throw new Error(`not HH:MM: ${JSON.stringify(time)}`);
  const [y, mo, d] = dateStr.split("-").map(Number);
  const [hh, mi] = time.split(":").map(Number);
  const wallMs = Date.UTC(y, mo - 1, d, hh, mi, 0);
  let t = wallMs;
  for (let i = 0; i < 3; i++) {
    const next = wallMs - offsetMinutes(tz, t) * 60_000;
    if (next === t) break;
    t = next;
  }
  const back = wallText(tz, t);
  if (back.slice(0, 16) !== `${dateStr}T${time}`) {
    throw new Error(`${dateStr} ${time} does not exist in ${tz} (it reads back as ${back}) - check the DST transitions for this series`);
  }
  return new Date(t).toISOString().replace(/\.\d{3}Z$/, "Z");
}

// ------------------------------------------------------------ the row's clock

/** Which zone a stored row's wall clock should be read in: the row's own declaration first, the series'
 *  only when the row declares none. `usedFallback` exists so the report can say which happened. */
function rowTimezone(row, series) {
  const declared = row?.options?.timezone;
  if (typeof declared === "string" && declared) return { tz: declared, usedFallback: false };
  return { tz: assertTimezone(series.timezone), usedFallback: true };
}

/** The local date of a stored row - the unit the dedupe key is compared on. */
function rowLocalDate(row, series) {
  return wallClock(row.beginsOn, rowTimezone(row, series).tz).date;
}

// ------------------------------------------------------------- the schedule

const CANCELLED = "CANCELLED";
const isLive = (row) => row.status !== CANCELLED;

/**
 * The next date the series should hold.
 *
 * Anchored on the last real occurrence, not on a hard-coded calendar: if the club skips a week the chain
 * keeps its rhythm from what actually happened, and if a human schedules the next date by hand the rule
 * steps past it. `skipDates` is "sometimes we miss one", expressed as data instead of as silence.
 */
function nextCandidate({ lastDate, everyDays, weekdaySnap, skipDates = [], todayDate, maxSteps }) {
  if (!Number.isInteger(Number(everyDays)) || Number(everyDays) < 1) throw new Error(`everyDays must be a positive integer, got ${JSON.stringify(everyDays)}`);
  const every = Number(everyDays);
  const skipped = [];
  let d = lastDate;
  for (let step = 1; step <= maxSteps; step++) {
    d = snapToWeekday(addDays(d, every), weekdaySnap);
    const iso = skipDates.map(String);
    if (iso.includes(d)) { skipped.push(d); continue; }
    if (cmpDate(d, todayDate) > 0) return { date: d, steps: step, skipped };
  }
  throw new Error(`no future date for this series within ${maxSteps} steps of ${lastDate} - the rhythm needs a human look (last occurrence ${lastDate}, everyDays ${every})`);
}

/** Copy the address without the fields that would make the new event *share* a row with the old one: an
 *  `id` here means "edit this address", and editing one event's venue would move the other's. */
function copyAddress(a) {
  if (!a) return undefined;
  const out = {};
  for (const k of ["street", "locality", "region", "postalCode", "country", "geom", "type", "description"]) {
    if (a[k] !== null && a[k] !== undefined) out[k] = a[k];
  }
  return Object.keys(out).length ? out : undefined;
}

/** Event options, copied on a whitelist. Deliberately *not* copied: `remainingAttendeeCapacity` (a count of
 *  who has already joined the old meeting) and `attendees` (a list of people). `timezone` is always the
 *  series' declared zone - that is the whole point of the clock rule.
 *
 *  `maximumAttendeeCapacity: 0` is also dropped. Measured 2026-11-04: the club's own live rows carry `0`,
 *  and their members attend them, so on this instance `0` is the "no limit" placeholder - but ActivityPub
 *  reserves `0` for "no attendees allowed", so the same number means two things in two layers. Copying it
 *  into a new public meeting is a defect either way, and dropping it fails in the safe direction: a meeting
 *  that admits more people than planned, not one that admits nobody. Set a real capacity on the source row
 *  and it is copied. */
function copyOptions(o, tz) {
  const out = { timezone: assertTimezone(tz) };
  for (const k of ["isOnline", "showStartTime", "showEndTime", "maximumAttendeeCapacity",
    "hideNumberOfParticipants", "hideOrganizerWhenGroupEvent", "commentModeration", "program"]) {
    if (o && o[k] !== null && o[k] !== undefined && !(k === "maximumAttendeeCapacity" && Number(o[k]) === 0)) out[k] = o[k];
  }
  return out;
}

/** The body of the write: a copy of the previous occurrence, with the clock and the zone re-derived. */
function buildCreateVars({ series, template, when, actorIds }) {
  const vars = {
    title: series.title,
    description: template.description ?? "",
    beginsOn: when.beginsOn,
    endsOn: when.endsOn,
    category: series.category || template.category || "MEETING",
    language: template.language || "en",
    draft: series.draft === true,
    visibility: series.visibility,
    status: "CONFIRMED",
    joinOptions: series.joinOptions || template.joinOptions || "FREE",
    tags: (template.tags ?? []).map((t) => t?.title).filter(Boolean),
    metadata: (template.metadata ?? [])
      .map((m) => ({ key: m.key, title: m.title, value: m.value, type: m.type }))
      .filter((m) => m.key && m.value !== undefined),
    contacts: (template.contacts ?? []).map((c) => ({ id: String(c.id) })).filter((c) => c.id),
    options: copyOptions(template.options, series.timezone),
    physicalAddress: copyAddress(template.physicalAddress),
    organizerActorId: String(actorIds.organizerActorId),
  };
  const attributedTo = actorIds.attributedToId ?? series.attributedToId;
  if (attributedTo) vars.attributedToId = String(attributedTo);
  if (series.copyPicture && template.picture?.uuid) vars.picture = { mediaUuid: template.picture.uuid };
  return vars;
}

// ------------------------------------------------------------ the decision

/**
 * One series in, one decision out. The order of the checks is the safety model:
 *
 * 1. no rows at all for this series  -> `alert` (a rename, or a series deleted: the loud answer, never a guess)
 * 2. where does the series stand today
 * 3. what date comes next, per the rule
 * 4. guards: horizon, catch-up, already-scheduled, another event on the same day, too many dates ahead
 * 5. only then: the payload, and `dryRun` decides whether it becomes `create` or `would_create`
 *
 * `alert` and `skip` both stop the write; they differ so the report can say "this needs a person" apart from
 * "nothing to do, correctly".
 */
function planSeries({ series, run, events, actorIds, nowIso }) {
  const notes = [];
  const all = Array.isArray(events) ? events : [];
  const rows = all.filter((r) => matchesSeries(series, r));
  const todayDate = wallClock(nowIso, assertTimezone(series.timezone)).date;

  if (!rows.length) {
    return {
      seriesKey: series.key, action: "alert", reason: "no_rows_for_series",
      note: `no event in ${series.groupActor} matches "${series.title}"${series.aliases?.length ? ` (or its aliases: ${series.aliases.join(", ")})` : ""} inside the read window. A rename, a deleted series, or a window that starts after the history.`,
      notes, todayDate,
    };
  }

  const live = rows.filter(isLive);
  if (!live.length) {
    return { seriesKey: series.key, action: "alert", reason: "every_row_cancelled", note: `${rows.length} rows match and all are CANCELLED.`, notes, todayDate };
  }

  const anchor = live.reduce((a, b) => (Date.parse(a.beginsOn) > Date.parse(b.beginsOn) ? a : b));
  const tzForAnchor = rowTimezone(anchor, series);
  const anchorClock = wallClock(anchor.beginsOn, tzForAnchor.tz);
  if (tzForAnchor.usedFallback) notes.push(`the anchor row declares no timezone; its clock was read in the series zone (${series.timezone})`);
  if (!tzForAnchor.usedFallback && tzForAnchor.tz !== series.timezone) {
    notes.push(`TIMEZONE: the anchor row declares ${tzForAnchor.tz} but the series declares ${series.timezone}; the wall clock ${anchorClock.time} was carried from the row and stamped ${series.timezone}. Fix the row in Mobilizon if that is not the club's real hour.`);
    if (series.strictTimezone === true) {
      return { seriesKey: series.key, action: "alert", reason: "timezone_mismatch", note: notes.at(-1), notes, todayDate };
    }
  }

  const duration = anchor.endsOn
    ? Math.round((Date.parse(anchor.endsOn) - Date.parse(anchor.beginsOn)) / 60_000)
    : Number(series.defaultDurationMinutes ?? 120);
  if (!anchor.endsOn) notes.push(`the anchor row has no end time; using the configured ${series.defaultDurationMinutes ?? 120} minutes`);
  if (duration <= 0 || duration > 24 * 60) {
    return { seriesKey: series.key, action: "alert", reason: "nonsense_duration", note: `anchor duration computed as ${duration} minutes.`, notes, todayDate };
  }

  const cand = nextCandidate({
    lastDate: anchorClock.date,
    everyDays: series.everyDays,
    weekdaySnap: series.weekdaySnap ?? null,
    skipDates: series.skipDates ?? [],
    todayDate,
    maxSteps: Number(run.maxCatchUpSteps ?? 6),
  });
  if (cand.skipped.length) notes.push(`skipDates held these back: ${cand.skipped.join(", ")}`);
  if (cand.steps > 1) notes.push(`caught up ${cand.steps} intervals from ${anchorClock.date} to ${cand.date} - the series had no row for a while`);

  const end = addMinutesToTime(anchorClock.time, duration);
  const when = {
    date: cand.date,
    time: anchorClock.time,
    timezone: series.timezone,
    beginsOn: instantFrom(cand.date, anchorClock.time, series.timezone),
    endsOn: instantFrom(addDays(cand.date, end.dayShift), end.time, series.timezone),
  };

  const decision = {
    seriesKey: series.key,
    seriesTitle: series.title,
    aliases: (series.aliases ?? []).slice(),
    action: null, reason: null, notes, todayDate,
    anchor: { uuid: anchor.uuid, id: anchor.id, title: anchor.title, beginsOn: anchor.beginsOn, url: anchor.url, declaredTimezone: tzForAnchor.tz },
    candidate: when,
  };

  // horizon: never write a date further out than the config allows, however the rhythm falls
  const horizonDate = fmtDate(parseDate(todayDate) + Number(run.horizonDays ?? 28) * DAY_MS);
  if (cmpDate(cand.date, horizonDate) > 0) {
    return { ...decision, action: "skip", reason: "beyond_horizon", note: `${cand.date} is more than ${run.horizonDays} days from ${todayDate}.` };
  }

  // dedupe: the series already holds this date - in whatever zone the existing row declares.
  // When is this reachable, given the anchor is the newest live row? Exactly when the row on the candidate
  // date is not live - today that means CANCELLED: the club cancelled Nov 21, the chain steps from Nov 7 to
  // Nov 21, and the guard refuses to resurrect a cancelled meeting on its own. It also catches the case a
  // future Mobilizon version or a different rule would make ordinary - a live row sitting on the computed
  // date - which is why it stays in front of the write rather than being deleted as dead code.
  const clash = rows.filter((r) => rowLocalDate(r, series) === cand.date);
  if (clash.length) {
    return {
      ...decision, action: "skip", reason: "already_scheduled",
      note: clash.map((r) => `${r.title} (${r.uuid}${r.status ? ", " + r.status : ""}) on ${cand.date}`).join("; "),
      clashes: clash.map((r) => ({ uuid: r.uuid, url: r.url, title: r.title, beginsOn: r.beginsOn, status: r.status, draft: r.draft })),
    };
  }
  // someone already put a different meeting on that night
  const otherSameDay = all.filter((r) => !matchesSeries(series, r) && rowLocalDate(r, series) === cand.date);
  if (otherSameDay.length && series.blockOnSameDayConflict !== false) {
    return {
      ...decision, action: "skip", reason: "other_event_same_day",
      note: otherSameDay.map((r) => `${r.title} (${r.uuid})`).join("; "),
    };
  }
  // enough dates ahead already
  const future = live.filter((r) => cmpDate(rowLocalDate(r, series), todayDate) > 0);
  if (future.length >= Number(series.maxFuturePerSeries ?? 2)) {
    return {
      ...decision, action: "skip", reason: "max_future_reached",
      note: `${future.length} future date(s) already scheduled: ${future.map((r) => rowLocalDate(r, series)).join(", ")}`,
    };
  }

  const leadDays = Math.round((parseDate(cand.date) - parseDate(todayDate)) / DAY_MS);
  if (leadDays < Number(series.minLeadDays ?? 2)) notes.push(`SHORT LEAD: this date starts in ${leadDays} day(s).`);

  const createVars = buildCreateVars({ series, template: anchor, when, actorIds: actorIds ?? {} });
  if (normTitle(anchor.title) !== normTitle(series.title)) {
    notes.push(`the new row is titled "${series.title}"; the row it was copied from is titled "${anchor.title}"`);
  }

  if (run.dryRun === true) {
    return { ...decision, action: "would_create", reason: "dry_run", createVars, leadDays };
  }
  return { ...decision, action: "create", reason: null, createVars, leadDays };
}

/**
 * A GraphQL response is not trustworthy because the transport succeeded. Measured on Mobilizon 5.2.4:
 * validation and authorization failures come back as **HTTP 200** with an `errors` array, and a partially
 * authorized query can carry `data` *and* `errors` together. So every caller of this integration unwraps
 * through here, and a response with errors ends the run with the server's own words in the message.
 */
function unwrap(response, label) {
  if (!response) throw new Error(`${label}: empty response`);
  if (Array.isArray(response.errors) && response.errors.length) {
    const detail = response.errors.map((e) => `${e.path ? e.path.join(".") + ": " : ""}${e.message ?? JSON.stringify(e)}`).join(" | ");
    throw new Error(`${label}: GraphQL error (HTTP reported success): ${detail}`);
  }
  if (!response.data) throw new Error(`${label}: no data in the GraphQL response`);
  return response.data;
}

/** The audit of the date we just wrote: the created event is present, and it is alone on that date.
 *  This is the duplicate guard that actually holds. Mobilizon offers no conditional create and no
 *  idempotency key, so the sequence can only be: read the date, decide, write, then prove what the date
 *  now holds. A same-second race with a human creating the same meeting is caught here and reported with
 *  both uuids rather than left for a member to notice. */
function auditDate({ plan, created, windowRows }) {
  const rows = Array.isArray(windowRows) ? windowRows : [];
  const series = { title: plan.seriesTitle, aliases: plan.aliases ?? [] };
  const mine = rows.find((r) => r.uuid === created?.uuid);
  const sameSeries = rows.filter((r) => matchesSeries(series, r));
  const problems = [];
  if (!mine) problems.push(`the created event (${created?.uuid}, ${created?.url}) is not in the group's list for ${plan.candidate.date}`);
  if (mine?.draft === true && plan.createVars?.draft !== true) problems.push("the event came back as a draft while the config asked for a published event");
  if (sameSeries.length > 1) {
    problems.push(`${sameSeries.length} rows for this series sit on ${plan.candidate.date}: ${sameSeries.map((r) => `${r.title} (${r.uuid}, ${r.url})`).join("; ")}`);
  }
  if (created && normTitle(created.title) !== normTitle(plan.createVars?.title)) problems.push(`the title came back as "${created.title}"`);
  if (created && Date.parse(created.beginsOn) !== Date.parse(plan.candidate.beginsOn)) {
    problems.push(`the instant came back as ${created.beginsOn}, expected ${plan.candidate.beginsOn}`);
  }
  return { ok: problems.length === 0, problems, seen: rows.length };
}

/** Is the alert channel usable? `ALERT` comes from `series.config.mjs` on the config item, so a reporter can
 *  answer this without knowing which host or topic is configured. A missing channel is not an error - the run
 *  still reports in the execution log - but it must be *said*, because "nobody was told" is the difference
 *  between a monitored job and an unmonitored one (D194). */
function canAlert(alert) {
  return !!(alert && alert.rootUrl && alert.topic && alert.tokenEnv);
}

/** The run summary, in the words a person reads. The execution log, the alert body, and `simulate.mjs`'s
 *  rehearsal all print these same lines, which is the point: a rehearsal that paraphrases the real report is
 *  a rehearsal of something else. `rows` is the per-series shape the reporters build
 *  ({ series, action, date, beginsOn, endsOn, why, audit, url, notes, wouldSend }). `payloads: false` is what
 *  a phone gets; the log gets them. */
function summaryLines({ rows, written, todayDate, payloads = true }) {
  const label = { create: "created", would_create: "dry run - would create", skip: "nothing to do", alert: "NEEDS A PERSON" };
  const lines = [`cadence: ${rows.length} series, ${written} event(s) written, at ${todayDate}`];
  for (const r of rows) {
    lines.push(`- ${r.series}: ${label[r.action] || r.action} ${r.date ?? "-"} ${r.beginsOn ?? ""}`.trimEnd());
    if (r.why) lines.push(`    why: ${r.why}`);
    if (r.url) lines.push(`    url: ${r.url}`);
    if (r.audit) lines.push(`    audit: ${r.audit}`);
    for (const n of r.notes ?? []) lines.push(`    note: ${n}`);
    // The full createEvent argument list belongs in the execution log, where a reviewer reads it line by line.
    // It is the *only* thing that differs from what a phone gets, because one JSON dump of a description
    // pushes every date out of the message cap - which is how an alert becomes "see the log", i.e. unread.
    if (payloads && r.wouldSend) lines.push(`    payload: ${JSON.stringify(r.wouldSend)}`);
  }
  return lines;
}

/** Which runs are worth a message, decided once (D194). Cadence runs every morning, so a message that means
 *  "nothing happened" is itself the failure mode: it trains a person to skim the channel, and the messages
 *  that matter get skimmed with it. So a plain skip is silent - the execution log remains the record - while
 *  a run that *wrote* something, or a dry run that decided exactly what it would write, says so out loud.
 *  `simulate.mjs` asks the same function, which is why the rule cannot drift between the workflow and the
 *  rehearsal. */
function runKind({ written = 0, wouldWrite = 0 } = {}) {
  return written ? "wrote" : wouldWrite ? "dryRun" : null;
}

/**
 * The marker `24 Fail loudly` puts at the front of the error it throws, and the marker the error watcher
 * looks for before deciding whether to speak (D206).
 *
 * Why a constant rather than a string in each node: cadence's own failure path already sends the message
 * (`23 Notify on ntfy`), and `24` exists only to keep the execution red. That throw is an *unhandled* error,
 * so once a workflow-level error workflow is linked it fires too - and without this marker the operator gets
 * two notifications for one incident, which is the exact shape D194 says makes a channel unread. One string,
 * thrown by one node and matched by one node, both built from this line.
 */
const LOUD_THROW = "cadence kept red on purpose";

/**
 * The error watcher's message, from the payload n8n hands an Error Trigger.
 *
 * The shape is read off the node's own source (`packages/nodes-base/nodes/ErrorTrigger/ErrorTrigger.node.ts`,
 * fetched 2026-11-05), which also ships the `mockManualExecution` example the node emits when you press
 * Execute Workflow on an error workflow: `{ execution: { id, url, retryOf, error: { message, stack },
 * lastNodeExecuted, mode }, workflow: { id, name } }`. Everything here is defensive because a watcher that
 * throws on an unexpected payload is a watcher that failed to watch - the vendor file flags the same drift
 * risk ("Error Trigger payload shape can change between versions").
 *
 * Returns `{ title, detail, click, duplicate, source }`. `duplicate: true` means cadence already told a
 * person about this run, so the watcher composes the message and stays quiet (the caller decides).
 */
function errorAlertFields(payload) {
  const ex = payload && typeof payload === "object" ? (payload.execution ?? {}) : {};
  const err = ex.error ?? {};
  const wf = payload?.workflow ?? {};
  const message = String(err.message ?? "(the error payload carried no message)");
  const nodeName = String(ex.lastNodeExecuted ?? "(unknown node)");
  const workflowName = String(wf.name ?? "(unknown workflow)");
  const lines = [];
  if (wf.name !== undefined) lines.push(`workflow   ${wf.name}${wf.id ? ` (${wf.id})` : ""}`);
  if (ex.id) lines.push(`execution  ${ex.id}${ex.retryOf ? ` (retry of ${ex.retryOf})` : ""}`);
  if (ex.url) lines.push(`open it    ${ex.url}`);
  lines.push(`failed at  ${nodeName}`);
  lines.push(`message    ${message.slice(0, 700)}`);
  if (err.description) lines.push(`detail     ${String(err.description).slice(0, 400)}`);
  if (Number.isFinite(err.timestamp)) {
    lines.push(`at         ${new Date(err.timestamp).toISOString()} (the payload's own epoch ms)`);
  }
  if (ex.mode) lines.push(`mode       ${ex.mode}`);
  return {
    title: `${workflowName} failed at ${nodeName}`,
    detail: lines.join("\n"),
    // Tapping the notification should open the run that broke, not the site: for a failure the evidence is the
    // execution. Falls back to the channel's default click when the payload has no url (older/newer n8n).
    click: ex.url || null,
    duplicate: message.startsWith(LOUD_THROW),
    source: { workflowId: wf.id ?? null, executionId: ex.id ?? null, node: nodeName },
  };
}

/**
 * The weekly heartbeat's report: what each series has coming, and whether the calendar is about to be empty.
 *
 * It deliberately does **not** call `planSeries`. The heartbeat is not a second planner - a second planner is a
 * second opinion that can disagree with the first in a message a person has to referee. It reports the rows
 * that exist, in the same wall-clock terms the planner uses (`rowLocalDate`, so a row declaring `Etc/UTC` and
 * a row declaring nothing are both read as the club reads them), and the only judgement it makes is the one
 * A8 already rules on: how many days until the next thing.
 */
function heartbeatReport({ series, events, nowIso, runwayDays }) {
  const todayDate = wallClock(nowIso, assertTimezone(series[0]?.timezone ?? "America/Chicago")).date;
  const rows = [];
  for (const s of series) {
    const live = (Array.isArray(events[s.groupActor]) ? events[s.groupActor] : [])
      .filter((r) => matchesSeries(s, r) && isLive(r) && r.draft !== true);
    const upcoming = live
      .filter((r) => cmpDate(rowLocalDate(r, s), todayDate) > 0)
      .sort((a, b) => Date.parse(a.beginsOn) - Date.parse(b.beginsOn));
    const next = upcoming[0] ?? null;
    const clock = next ? wallClock(next.beginsOn, rowTimezone(next, s).tz) : null;
    rows.push({
      series: s.key,
      group: s.groupActor,
      count: upcoming.length,
      nextDate: clock ? clock.date : null,
      nextTime: clock ? `${clock.time} ${clock.tz}` : null,
      daysOut: clock ? Math.round((parseDate(clock.date) - parseDate(todayDate)) / DAY_MS) : null,
      title: next ? next.title : null,
      url: next ? next.url : null,
    });
  }
  const empty = rows.filter((r) => !r.nextDate);
  const far = rows.filter((r) => r.nextDate && r.daysOut > Number(runwayDays));
  const kind = empty.length ? "problem" : far.length ? "runway" : "heartbeat";
  return { todayDate, rows, kind, empty: empty.map((r) => r.series), far: far.map((r) => r.series) };
}

/** The heartbeat's words, in the same register as `summaryLines`: the execution log, the ntfy message and
 *  `simulate.mjs --heartbeat` all print these exact lines. */
function heartbeatLines({ report, runwayDays }) {
  const lines = [`heartbeat: ${report.rows.length} series, calendar read at ${report.todayDate}`];
  for (const r of report.rows) {
    lines.push(r.nextDate
      ? `- ${r.series}: next ${r.nextDate} ${r.nextTime ?? ""} (${r.daysOut}d out, ${r.count} row(s) ahead)`
      : `- ${r.series}: NOTHING scheduled after ${report.todayDate} - no row in ${r.group} is upcoming`);
    if (r.url) lines.push(`    next row: ${r.title} ${r.url}`);
  }
  if (report.empty.length) lines.push(`    PROBLEM: no upcoming row for ${report.empty.join(", ")} - cadence either did not run, refused, or is not activated`);
  if (report.far.length) lines.push(`    RUNWAY: the next row for ${report.far.join(", ")} is more than ${runwayDays} days out - the same threshold A8's check:ics gates the site on (D188)`);
  lines.push(`    this message is the proof of life: if it stops arriving, n8n is not running this workflow - check it is activated.`);
  return lines;
}

/** The one message shape for the alert channel. Three reporters need it (a stage that threw, a plan that
 *  stopped, a run that wrote something), and a message that differs by path is a message nobody can learn to
 *  read - so the fields live here and the reporters only supply the words.
 *
 *  Field names are quoted from ntfy's JSON-publish example (read 2026-11-04): `topic`, `title`, `message`,
 *  `priority`, `tags`, `click`. Priorities are the documented ones - 4 high, 3 default, 2 low - and a caller
 *  that asks for an unknown kind gets the default rather than a rejected message. */
function alertBody({ alert, kind, title, detail, click }) {
  if (!canAlert(alert)) return null;
  const cap = alert.maxMessageChars || 1000;
  const priority = (alert.priority || {})[kind] || 3;
  const tags = kind === "problem" ? (alert.tags || {}).problem : undefined;
  const opens = click || alert.click;
  return {
    topic: alert.topic,
    title: String(title || "cadence").slice(0, 256),
    message: String(detail || "(no detail)").slice(0, cap),
    priority,
    ...(tags && tags.length ? { tags } : {}),
    ...(opens ? { click: opens } : {}),
  };
}
/**
 * The series table - the one place a maintainer edits to change what this integration does.
 *
 * This file is the source of truth for both hosts: `simulate.mjs` imports it, and `build-workflow.mjs`
 * inlines it into the n8n "01 Config" Code node. There is no copy of it inside n8n to keep in step.
 *
 * Every value here is either quoted from the organizer's own Mobilizon rows or chosen as an operating
 * limit and labelled as one. Nothing here states a cadence as a fact about the club (D92 keeps frequency
 * words off the site); these are the spacing rules the automation will *try* to hold, measured from the
 * rows in `fixtures/group-history-2026-11-04.json` (read from the live instance 2026-11-04):
 *
 *   MPLS Math Club - Bimonthly Social       2026-05-08, 05-22, 06-05, 11-07   14 days apart, Saturdays
 *   Parallel Learning for Mathematical Minds 2026-11-11                        Wednesdays, "twice a month"
 *
 * If the organizer's real rhythm is not 14 days, change `everyDays` here - that is the whole point of
 * keeping the rhythm as data rather than as a rule engine.
 */

const INSTANCE = {
  // Measured 2026-11-04 on Mobilizon 5.2.4: the GraphQL endpoint on this instance is `/api/v1`.
  // `/graphql` answers 404 `{"msg":"Resource not found"}`, which is what the public docs imply you should
  // use - so the path is recorded here rather than remembered.
  baseUrl: "https://mobilizon.labradorius.com",
  graphqlPath: "/api/v1",
  // The n8n nodes use the absolute URL literally. This is here so a reader, and the build's own assertion,
  // can see which host this integration is allowed to write to.
  expectedHost: "mobilizon.labradorius.com",
  // The workflow's own clock zone. The trigger says 09:00 and this is what that means; leaving it to the n8n
  // instance default is how a schedule quietly moves when the host is rebuilt.
  timezone: "America/Chicago",
};

/**
 * Where the Mobilizon account lives - **by name only**. These are the names of environment variables set on
 * the n8n host (see README, "Credentials"); the workflow reads them with `$env`, so no password exists in the
 * repo, in the workflow JSON, or in the config item that every node can see. The build refuses this field if
 * it is ever given a value instead of a NAME.
 *
 * Mobilizon 5.2.4 offers no long-lived API token, and this workflow signs in per run with this account. OAuth
 * does exist on the instance - but on the apex (`POST /apps`), not under `/api/v1`, and its grants need a
 * one-time human authorisation plus a rotating refresh token (measured and read in lib/queries.mjs; D185), so
 * it moves the secret rather than removing it. If the operator chooses a scoped service account, `03 Sign in`
 * is the only node that changes.
 */
const CREDENTIALS = {
  emailEnv: "MOBILIZON_EMAIL",
  passwordEnv: "MOBILIZON_PASSWORD",
};

const RUN = {
  /**
   * `true` computes everything and writes nothing: the decision arrives as `would_create` with the exact
   * payload it would have sent, printed in the report. Flip to `false` after watching one dry run you agree
   * with. This is the only kill switch, so it is deliberately the first line of the config.
   */
  dryRun: true,
  /** Never write a date further out than this. A series whose rule points past the horizon is skipped -
   *  the club stays able to plan by hand, and a runaway loop cannot fill next year. */
  horizonDays: 28,
  /** How far past the last existing row the rule may reason while catching up. Past this the run alerts
   *  instead of inventing a chain of dates nobody asked for. */
  maxCatchUpSteps: 6,
  /** The read window, in days. Back: enough history to see the rhythm and survive a long gap. Forward:
   *  enough to see every date the club has already scheduled by hand. */
  readBackDays: 400,
  readAheadDays: 120,
  readLimit: 100,
};

/**
 * Execution retention, in the runtime's own words (D201, 2026-11-05).
 *
 * Measured on the live instance by A/B on a throwaway workflow: the YunoHost package ships
 * `EXECUTIONS_DATA_SAVE_ON_SUCCESS=none` and `EXECUTIONS_DATA_SAVE_MANUAL_EXECUTIONS=false` in its rendered `.env`,
 * so a successful run - manual or scheduled - is never persisted. The symptom is not an error: the run returns
 * an execution id, and reading it answers `Execution '2' not found`. A dry run nobody can read is a dry run
 * nobody ran, so both artifacts declare their own retention, and the A/B proved the workflow's settings beat
 * the instance default.
 *
 * Per-workflow rather than instance-wide on purpose (operator ruling 2026-11-05, "1c"): instance-wide `all`
 * would also keep every other workflow's run data - one of which may hold a password - and a hand-edited `.env`
 * is re-rendered from the package template at the next `yunohost app upgrade` (D199).
 *
 * What this costs, named rather than argued: with success data stored, this workflow's own run records hold the
 * sign-in request body. Whether n8n 2.45.7 masks a `$env` password inside stored run data is **not measured**,
 * so pruning stays a host job (docs/security.md) and `verify-import.mjs` prints this as a NOTE, not a pass.
 */
const RETENTION = {
  saveDataErrorExecution: "all",
  saveDataSuccessExecution: "all",
  savePreExecutionData: false,
  saveManualExecutions: true,
};

/**
 * The alert channel - **one topic on the operator's own ntfy server** (D194, adopted 2026-11-04).
 *
 * Measured on 2026-11-04 from this workspace (Linux), so a future session does not re-guess it:
 *   - `ntfy.labradorius.com` resolves CNAME `labradorius.com` -> `75.73.33.126` - **public**, not LAN-only,
 *     unlike `mobilizon.labradorius.com` (192.168.1.120). So the alert reaches a phone off the LAN, and
 *     nothing can poll the Mobilizon host from away from home.
 *   - Anonymous publish and anonymous poll are both refused: `POST /<topic>` -> `{"code":40301,"http":403,
 *     "error":"forbidden"}` and `GET /<topic>/json?poll=1` -> the same. `GET /v1/version` -> `40101`. That is
 *     the YunoHost package's own posture, read from its `conf/server.yml`: `auth-default-access: "deny-all"`
 *     plus `enable-login: true`, and `ntfy access everyone "up*" wo` at install (so **a topic must not start
 *     with `up`** - the package grants anonymous write-only there for its iOS upstream flow).
 *   - So the channel needs a credential: an ntfy **access token** in an n8n environment variable, exactly like
 *     the Mobilizon password (`CREDENTIALS`). ntfy tokens are `tk_`-prefixed and - measured from the upstream
 *     docs - "grant users full access to the user account", i.e. they are **not topic-scoped**. Least privilege
 *     therefore comes from the *account*: a purpose-built non-admin user whose ACL entry is
 *     `read-write` on this one topic and nothing else. See docs/operator-guide.md for the commands.
 *   - E-mail is not the channel: `labradorius.com` has no apex TXT (no SPF) and no MX record (measured
 *     2026-11-04 by `dig`), and the n8n package's pre-wired SMTP points at the YunoHost mail server that those
 *     records say is not set up for sending. Discord is the fallback (the repo already has a Discord webhook
 *     gate); ntfy was chosen because it is one `POST`, self-hosted, needs no bot, and works on a phone with no
 *     account beyond the topic.
 *
 * The URL is the **root**, not a topic path: ntfy accepts the whole message as a JSON body only when the
 * request goes to the server root ("To publish as JSON, you must PUT/POST to the ntfy root URL, not to the
 * topic URL" - docs, read 2026-11-04). That keeps the httpRequest node in the same `specifyBody: "json"` shape
 * as every other HTTP node in this workflow, so there is no second body style to review.
 */
const ALERT = {
  provider: "ntfy",
  host: "ntfy.labradorius.com",
  rootUrl: "https://ntfy.labradorius.com/",
  /** Topic ids in ntfy are `[a-zA-Z0-9_-]{1,64}`. `mathloco-` prefixes it so a topic on a shared home server
   *  still says which project it belongs to, and it deliberately does not start with `up` (see above). */
  topic: "mathloco-cadence",
  /** Name of the n8n environment variable holding the `tk_...` token - a NAME, never a value, under the same
   *  rule as `CREDENTIALS` (the build refuses a value, and the token never enters the workflow JSON). */
  tokenEnv: "NTFY_TOKEN",
  /** What tapping the notification opens. The public schedule page, because that is the thing an alert is
   *  about, and reading it is how you tell whether the alert is stale. */
  click: "https://minneapolismathbookclub.com/#when-we-meet",
  /** Priorities are measured from the upstream table: 5 max (long vibration, pop-over), 4 high, 3 default,
   *  2 low (no sound, drawer only), 1 min. Nothing here is a 5: these messages arrive at 09:00 and a calendar
   *  problem is not a three-in-the-morning emergency. A run with nothing to say sends nothing at all.
   *
   *  `heartbeat` is the weekly proof of life (D205): quiet on purpose, because it arrives whether or not
   *  anything happened, and a message that buzzes once a week is a message that gets read.
   *  `runway` is that same message when the calendar it reports is empty further out than
   *  `HEARTBEAT.runwayDays` - the site's own staleness gate (A8, D188) would go loud about that, so the
   *  heartbeat stops being noise and becomes the early half of it. */
  priority: { problem: 4, wrote: 4, dryRun: 2, heartbeat: 2, runway: 4 },
  /** Only `warning` is used, because that tag name is quoted from the upstream examples. Other emoji tags are
   *  plausible but unverified here, and an unknown tag name is a message that fails to publish. */
  tags: { problem: ["warning"] },
  /** The message text is capped here as well as in the reporters, so a 400 from ntfy is not how a person finds
   *  out something went wrong. (ntfy's own limit was not measured; 1000 chars is far under the 4096-byte
   *  figure in the message-format docs, which is the number to re-check if this ever truncates.) */
  maxMessageChars: 1000,
  /** A second channel for the error watcher only, and it is **off** (D206).
   *
   *  The vendor set names the recursion trap outright: if the error workflow's own channel is the channel the
   *  monitored workflow uses, then the outage that caused the failure also eats the alert about it, and n8n
   *  does not re-trigger on the error workflow's failure ("no infinite loop, but the failure goes nowhere").
   *  Its mitigations are "use a different channel" or "have a fallback".
   *
   *  Shipped null because a fallback needs a secret that does not exist yet: the club's Discord side is a bot
   *  token for the site Worker (`DISCORD_TOKEN`, wrangler.toml), not an incoming webhook URL, and inventing an
   *  environment variable name for a credential nobody has minted is how a workflow ships a node that can only
   *  fail. To turn it on: create a Discord webhook for a club channel, put its URL in an n8n environment
   *  variable by NAME, and set
   *
   *      fallback: { kind: "discord", urlEnv: "MATHLOCO_ALERT_WEBHOOK", maxMessageChars: 1800 }
   *
   *  `build-alerter.mjs` then emits `A4 Notify on the fallback`, wired to `A3`'s error output, and
   *  `checkAlerter()` polices the pair (`onError` without the wire, or the wire without `onError`, is the
   *  silent-failure shape this repo has already been bitten by twice). Until then the honest statement is in
   *  docs/security.md: one channel, and the weekly heartbeat is the backstop for "the channel is down". */
  fallback: null,
};

/**
 * The weekly heartbeat (operator ruling 2026-11-05, "weekly heartbeat can be built now"; D205).
 *
 * What it is for: every other message on this topic means "something happened". D194's silence rule makes
 * that deliberate, and it leaves one hole no per-node error output can close - a scheduler that is simply not
 * running sends nothing, and nothing looks identical to a quiet week. A8's runway gate (`check:ics`,
 * N = 21 days, D188) is the only detector today, and it is a *deploy-time* detector on the *site's* snapshot,
 * so the honest latency of "n8n is dead" is about three weeks. One message a week cuts that to seven days.
 *
 * It trades directly against D194, which is why it was a ruling and not a code change: one message that means
 * "still alive" is the price of being able to notice death.
 *
 * It is not only a ping. It reads the same public calendar cadence reads (no credential - the same read
 * `simulate.mjs` makes) and prints the next date each series holds and how far out it is, so the weekly note
 * answers "is the calendar actually full?" as well as "is n8n alive?". Past `runwayDays` it goes to priority 4
 * and names the fix, which makes it the early-warning half of A8's rule rather than a third opinion on it.
 */
const HEARTBEAT = {
  /** 0 = Sunday ... 1 = Monday, measured against this instance's own node source: Schedule Trigger v1 takes
   *  `triggerAtDay` (an array of these numbers), `triggerAtHour` and `triggerAtMinute` - there is no `triggerAt`
   *  string (D207). `build-heartbeat.mjs` asserts its own trigger block against these three names. */
  weekday: 1,
  hour: 9,
  minute: 0,
  everyWeeks: 1,
  /** How far ahead of the next row the calendar may sit empty before the weekly note goes loud.
   *  Deliberately the same number as A8's `RUNWAY_DAYS` (scripts/check-ics.mjs, D188): one threshold for
   *  "the club is about to have nothing to attend", raised by the runtime at 7 days and by the deploy gate
   *  at 21. If one moves, move both, and the comment in check-ics.mjs points back here. */
  runwayDays: 21,
  /** The public read the heartbeat makes. Forward only: it is asking "what is coming", not re-deriving the
   *  rhythm, and a short window keeps the response small enough to read in one execution. */
  readAheadDays: 60,
  readLimit: 100,
  /** Structural, not decorative: the heartbeat has no `Tell a person?` gate, because a heartbeat that can be
   *  skipped is the same silence it exists to detect. `checkHeartbeat()` fails the build if an IF node appears. */
  alwaysSend: true,
};

const SERIES = [
  {
    key: "mpls-social", // stable id; never reuse it for a different series
    // Quoted from the organizer's row, verbatim. This string is the dedupe key as well as the new row's
    // title, so an edit here must match the Mobilizon title or the series stops being recognised (the run
    // will alert rather than silently create a second series).
    // The word "Bimonthly" is the organizer's, not ours: D92 keeps frequency words off the *site*, and the
    // harvester already quotes this title rather than rewriting it.
    title: "MPLS Math Club - Bimonthly Social",
    aliases: ["MPLS Math Club Social", "Bimonthly Social"], // earlier titles, so a rename does not orphan the history
    groupActor: "minneapolis_math_book_group",

    everyDays: 14,      // the spacing in the rows above
    weekdaySnap: 6,     // 6 = Saturday: pull the date back onto the club's weekday if a row drifts
    timezone: "America/Chicago", // declared, never inferred (see lib/core.mjs, "The clock rule")
    skipDates: [],      // "sometimes we miss one", as data: ["2026-12-19"]

    maxFuturePerSeries: 2, // stop once this many future dates exist; the club plans ahead by hand past that
    minLeadDays: 2,        // write anyway, but say so, if the date starts sooner than this
    strictTimezone: false, // true = alert instead of writing when a row's declared zone is not the series'

    // What the new row looks like to members
    visibility: "PUBLIC",
    joinOptions: "FREE",
    draft: false,            // true = park it as a draft for a human to publish
    copyPicture: true,       // carry the club's event art by reference (`picture.mediaUuid`), verified 2026-11-04
    blockOnSameDayConflict: true, // another group event already on that date -> skip and say so
  },
  {
    key: "parallel-learning",
    title: "Parallel Learning for Mathematical Minds",
    aliases: [],
    groupActor: "minneapolis_math_book_group",
    // 14 days is the club's stated cadence, not a measured one: Mobilizon holds exactly ONE row for this
    // series (2026-11-11, saved in fixtures/group-history-2026-11-04.json), so there is no gap history here to
    // take a mode of. "twice a month on weekday evenings" is quoted from that row's own description, and 14 is
    // also the spacing the social series' four rows show (14, 14, then a 155-day summer gap). Revisit once a
    // few parallel sessions exist - the anchor is the newest row, so history in Mobilizon is what this tracks.
    everyDays: 14,
    // No snap: 14 days from a weekday lands on the same weekday, so there is nothing to correct - and if a
    // human moves one session to a Tuesday, the next should stay a Tuesday. This series' own description says
    // "weekday evenings", not a named day. mpls-social keeps its snap because the club has stated a Saturday
    // pattern that a one-off weekday should not silently replace.
    weekdaySnap: null,
    timezone: "America/Chicago",
    skipDates: [],
    maxFuturePerSeries: 2,
    minLeadDays: 2,
    strictTimezone: false,
    visibility: "PUBLIC",
    joinOptions: "FREE",
    draft: false,
    copyPicture: true,
    blockOnSameDayConflict: true,
  },
];
const cfg = (() => { try { return $("H1 Config").item.json; } catch (e) { return null; } })();
if (!cfg) throw new Error("H3: H1 Config produced no item, so the heartbeat has no series table to report on");

// A GraphQL error comes back as HTTP 200 with an `errors` array on this instance, so the response is unwrapped
// rather than trusted. If it throws, the run goes red - and if the watcher is linked, a person hears about a
// dead heartbeat read within a minute of it happening rather than up to a week later.
const body = (() => { try { return $("H2 Read the calendar").item.json; } catch (e) { return null; } })();
const data = unwrap(body, "H2 Read the calendar");
const group = data.group;
if (!group) {
  throw new Error(`H3: the instance returned no group for "${cfg.groupActor}" - the heartbeat cannot report on a calendar it cannot find`);
}

const eventsByGroup = { [cfg.groupActor]: group.organizedEvents?.elements ?? [] };
const report = heartbeatReport({
  series: cfg.SERIES,
  events: eventsByGroup,
  nowIso: cfg.runAt,
  runwayDays: cfg.HEARTBEAT.runwayDays,
});
const lines = heartbeatLines({ report, runwayDays: cfg.HEARTBEAT.runwayDays });

const head = report.rows.map((r) => `${r.series} ${r.nextDate ? `+${r.daysOut}d` : "EMPTY"}`).join(", ");
const title = report.kind === "heartbeat"
  ? `cadence heartbeat: alive, ${head}`
  : report.kind === "runway"
    ? `cadence heartbeat: THIN RUNWAY - ${head}`
    : `cadence heartbeat: NO UPCOMING ROW - ${head}`;

const detail = [
  `weekly heartbeat for ${cfg.groupActor} at ${cfg.runAt}`,
  ...lines,
  "",
  `cadence writes the next row itself; it fires daily at the hour in its own settings.timezone, and its kill switch is RUN.dryRun in series.config.mjs.`,
  `the site's own staleness gate (check:ics, ${cfg.HEARTBEAT.runwayDays}-day runway, D188) fails a publish on the same condition - this is the earlier half of it.`,
].join("\n");

return [{ json: {
  ok: report.kind === "heartbeat",
  heartbeat: true,
  kind: report.kind,
  todayDate: report.todayDate,
  rows: report.rows,
  empty: report.empty,
  far: report.far,
  alertTitle: title,
  summary: lines.join("\n"),
  // Not a decision node: this workflow has no gate, so every run that reaches here sends. The field exists so
  // the execution log says so out loud rather than leaving a reader to infer it from the wiring.
  notifyNeeded: canAlert(cfg.ALERT),
  alertChannel: canAlert(cfg.ALERT) ? cfg.ALERT.topic : "none configured",
  ntfy: alertBody({ alert: cfg.ALERT, kind: report.kind, title, detail }),
} }];
